220	function makeRequest(body: Record<string, unknown>): NextRequest {
221	  return new NextRequest('http://localhost/api/payments/charge', {
222	    method: 'POST',
223	    headers: { 'Content-Type': 'application/json' },
224	    body: JSON.stringify(body),
225	  })
226	}
